use quince_core::{ring::RingVec,types::Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:2.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_donchian_width",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,v:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{Ok(Box::new(I{p:x[0]as usize,v:RingVec::new(x[0]as usize)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{self.v.push(t.price);(self.v.len()==self.p).then(||self.v.iter().fold(f64::NEG_INFINITY,f64::max)-self.v.iter().fold(f64::INFINITY,f64::min))}}
